#!/usr/bin/env node
/**
 * Checks fdm-core Drizzle schema files against the conventions documented in
 * .github/skills/fdm-schema/SKILL.md.
 *
 * Zero dependencies, no database and no build required, so it can run as a fast CI gate.
 * The parsing is line-based rather than a full TypeScript parse; that is deliberate.
 *
 * Usage:
 *   node .github/skills/fdm-schema/scripts/check-schema-conventions.mjs [--json] [--strict]
 *
 *   --json    machine-readable output
 *   --strict  also report the advisory rules (missing unit comments), which are noisy on the
 *             existing catalogue tables and therefore off by default in CI
 */

import { readFileSync } from "node:fs"
import { dirname, join, relative, resolve } from "node:path"
import { fileURLToPath } from "node:url"

const repoRoot = resolve(dirname(fileURLToPath(import.meta.url)), "../../../..")

/** schema-authn.ts is generated by better-auth and is camelCase by design; never checked. */
const SCHEMA_FILES = [
  "fdm-core/src/db/schema.ts",
  "fdm-core/src/db/schema-authz.ts",
  "fdm-core/src/db/schema-calculator.ts",
]

/**
 * The `fdm` PG schema is the farm data model and uses the domain prefix vocabulary.
 * `fdm-authz` and `fdm-calculator` are infrastructure schemas and use plain snake_case.
 */
const DOMAIN_SCHEMA = "fdm"

/** Domain prefixes from the SKILL.md glossary. l_ and f_ are reserved for livestock and feed. */
const DOMAIN_COLUMN_NAME = /^(?:[bpamlf]_[a-z0-9_]+|created|updated)$/
const INFRA_COLUMN_NAME = /^[a-z][a-z0-9_]*$/

/**
 * Exemptions, each with the reason. Add an entry only when the exception is genuinely
 * correct; the default answer to a violation is to fix the schema.
 */
const ALLOWLIST = {
  /** Tables that legitimately have no created/updated columns. */
  timestamps: {
    "fdm-authz.audit": "append-only audit log; carries its own audit_timestamp",
    "fdm-authz.role": "join table maintained exclusively through the authorization helpers",
    "fdm-authz.invitation": "lifecycle is tracked by status/expires/accepted_at",
    "fdm-calculator.calculation_cache": "cache rows are immutable and use created_at",
    "fdm-calculator.calculation_errors": "error rows are immutable and use created_at",
  },
  /** Tables whose $inferSelect/$inferInsert types are intentionally not exported. */
  types: {},
  /** Columns where jsonb is correct because the payload is genuinely open-ended. */
  jsonb: {
    "fdm.soil_image_annotating.a_image_annotation_coordinates":
      "free-form point/polygon coordinate list drawn on an image",
    "fdm-authz.audit.audit_resource_details": "arbitrary snapshot of the audited resource",    "fdm-authz.audit.audit_origin_details": "arbitrary request metadata",
    "fdm-calculator.calculation_cache.input": "opaque calculator input, keyed by calculation_hash",
    "fdm-calculator.calculation_cache.result": "opaque calculator result",
    "fdm-calculator.calculation_errors.input": "opaque calculator input reproducing the failure",
  },
  /** Columns exempt from the naming rule. */
  columns: {
    "fdm.fertilizers_catalogue.hash": "content hash used to detect fdm-data catalogue changes",
    "fdm.cultivations_catalogue.hash": "content hash used to detect fdm-data catalogue changes",
    "fdm.measures_catalogue.hash": "content hash used to detect fdm-data catalogue changes",
    "fdm.animal_categories_catalogue.hash":
      "content hash used to detect fdm-data catalogue changes",
  },
}

const strict = process.argv.includes("--strict")
const findings = []

/** Escapes every regex metacharacter, so identifiers read from the schema are matched literally. */
function escapeRegExp(value) {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")
}

function report(level, rule, file, line, message) {
  findings.push({ level, rule, file, line, message })
}

/**
 * Splits a schema file into table declarations.
 * Matches both `x = s.table("name", {` and the multi-line `x = s.table(\n  "name",\n  {` form.
 */
function parseTables(source, lines) {
  const tables = []
  const re = /export const (\w+) = (\w+)\.table\(\s*(?:\/\/[^\n]*\n\s*)?"([^"]+)"\s*,/g
  let match
  while ((match = re.exec(source)) !== null) {
    const [, constName, schemaObject, tableName] = match
    const startLine = source.slice(0, match.index).split("\n").length
    const body = extractColumnBody(lines, startLine - 1)
    tables.push({ constName, schemaObject, tableName, startLine, ...body })
  }
  return tables
}

/**
 * Collects the column definitions of a table by walking forward from its declaration and
 * tracking brace depth, so nested option objects and callbacks are not mistaken for columns.
 */
function extractColumnBody(lines, startIndex) {
  const columns = []
  let depth = 0
  let started = false
  let endLine = startIndex

  for (let i = startIndex; i < lines.length; i++) {
    const line = lines[i]
    const code = line.replace(/\/\/.*$/, "")

    for (const char of code) {
      if (char === "{") depth++
      else if (char === "}") depth--
    }

    if (!started && depth > 0) started = true

    if (started && depth === 1) {
      const colMatch = line.match(/^\s*([A-Za-z_][A-Za-z0-9_]*)\s*:\s*\S/)
      if (colMatch) {
        columns.push({ name: colMatch[1], line: i + 1, text: line.trim() })
      }
    }

    if (started && depth === 0) {
      endLine = i + 1
      break
    }
    endLine = i + 1
  }

  return { columns, endLine }
}

function checkFile(relPath) {
  let source
  try {
    source = readFileSync(join(repoRoot, relPath), "utf8")
  } catch {
    report("error", "missing-file", relPath, 0, "schema file not found")
    return
  }

  const lines = source.split("\n")
  const pgSchemas = new Map()
  const schemaRe = /export const (\w+) = pgSchema\("([^"]+)"\)/g
  let schemaMatch
  while ((schemaMatch = schemaRe.exec(source)) !== null) {
    pgSchemas.set(schemaMatch[1], schemaMatch[2])
  }

  const tables = parseTables(source, lines)
  if (tables.length === 0) {
    report("error", "no-tables", relPath, 0, "no table declarations found — the parser may be out of date")
    return
  }

  for (const table of tables) {
    const pgSchema = pgSchemas.get(table.schemaObject) ?? table.schemaObject
    const qualified = `${pgSchema}.${table.tableName}`
    const isDomain = pgSchema === DOMAIN_SCHEMA

    // Rule: domain columns carry a prefix; infrastructure columns are plain snake_case.
    for (const column of table.columns) {
      const key = `${qualified}.${column.name}`
      if (ALLOWLIST.columns[key]) continue
      const pattern = isDomain ? DOMAIN_COLUMN_NAME : INFRA_COLUMN_NAME
      if (!pattern.test(column.name)) {
        report(
          "error",
          "column-naming",
          relPath,
          column.line,
          isDomain
            ? `${key} — expected a b_/p_/a_/m_/l_/f_ prefixed snake_case name, or created/updated`
            : `${key} — expected a lowercase snake_case name`,
        )
      }
    }

    // Rule: every fdm table is auditable via created/updated.
    if (isDomain && !ALLOWLIST.timestamps[qualified]) {
      const names = new Set(table.columns.map((c) => c.name))
      for (const required of ["created", "updated"]) {
        if (!names.has(required)) {
          report("error", "timestamps", relPath, table.startLine, `${qualified} has no \`${required}\` column`)
        }
      }
    }

    // Rule: downstream packages import the inferred types, so both must be exported.
    if (!ALLOWLIST.types[qualified]) {
      for (const kind of ["TypeSelect", "TypeInsert"]) {
        const infer = kind === "TypeSelect" ? "$inferSelect" : "$inferInsert"
        const expected = new RegExp(
          `export type \\w*${kind}\\s*=\\s*typeof ${escapeRegExp(table.constName)}\\.${escapeRegExp(infer)}`,
        )
        if (!expected.test(source)) {
          report(
            "error",
            "inferred-types",
            relPath,
            table.startLine,
            `${qualified} does not export a \`typeof ${table.constName}.${infer}\` type`,
          )
        }
      }
    }

    // Rule: structured data belongs in typed columns, not a jsonb bag.
    for (const column of table.columns) {
      if (!/\bjsonb\(/.test(column.text)) continue
      if (ALLOWLIST.jsonb[`${qualified}.${column.name}`]) continue
      report(
        "warn",
        "jsonb",
        relPath,
        column.line,
        `${qualified}.${column.name} uses jsonb — prefer typed columns or a dedicated table, or allowlist it with a reason`,
      )
    }

    // Rule: numeric agronomic values document their unit. Advisory: --strict only.
    if (isDomain && strict) {
      for (const column of table.columns) {
        if (!/\bnumericCasted\(/.test(column.text)) continue
        if (/\/\/\s*\S/.test(column.text)) continue
        report(
          "warn",
          "unit-comment",
          relPath,
          column.line,
          `${qualified}.${column.name} is numeric but has no trailing unit comment (e.g. \`// kg N / ha\`)`,
        )
      }
    }
  }

  // Rule: an enum's PostgreSQL name equals the column it is used for.
  const enumRe = /export const (\w+) = (\w+)\.enum\(\s*"([^"]+)"/g
  let enumMatch
  while ((enumMatch = enumRe.exec(source)) !== null) {
    const [, constName, schemaObject, enumName] = enumMatch
    const line = source.slice(0, enumMatch.index).split("\n").length
    const isDomainEnum = (pgSchemas.get(schemaObject) ?? schemaObject) === DOMAIN_SCHEMA
    const pattern = isDomainEnum ? DOMAIN_COLUMN_NAME : INFRA_COLUMN_NAME
    if (!pattern.test(enumName)) {
      report(
        "error",
        "enum-naming",
        relPath,
        line,
        `enum ${constName} is named "${enumName}" — the PG enum name must equal the column name it is used for`,
      )
      continue
    }
    const used = new RegExp(`^\\s*${escapeRegExp(enumName)}\\s*:\\s*${escapeRegExp(constName)}\\(`, "m").test(source)
    if (!used) {
      report(
        "warn",
        "enum-naming",
        relPath,
        line,
        `enum ${constName} is named "${enumName}" but no column of that name uses it`,
      )
    }
  }
}

for (const file of SCHEMA_FILES) checkFile(file)

const errors = findings.filter((f) => f.level === "error")
const warnings = findings.filter((f) => f.level === "warn")

if (process.argv.includes("--json")) {
  console.log(JSON.stringify({ errors, warnings }, null, 2))
} else {
  for (const finding of findings) {
    const label = finding.level === "error" ? "ERROR" : "warn "
    console.log(`${label} ${finding.file}:${finding.line}  [${finding.rule}] ${finding.message}`)
  }
  const scope = SCHEMA_FILES.map((f) => relative(".", f)).join(", ")
  if (findings.length === 0) {
    console.log(`fdm-schema conventions: OK (${scope})`)
    if (!strict) console.log("Run with --strict to also report missing unit comments.")
  } else {
    console.log(`\nfdm-schema conventions: ${errors.length} error(s), ${warnings.length} warning(s)`)
    console.log("See .github/skills/fdm-schema/SKILL.md for the rules behind each check.")
  }
}

process.exit(errors.length > 0 ? 1 : 0)
